document.addEventListener("DOMContentLoaded", function () {
    // === TOP HERO animations (GSAP + IO, no ScrollTrigger) ===



    // Helpers
    const IO_OPTIONS = { threshold: 0.1 }; // 10%
    const playOnce = (cb) => {
        let played = false;
        return (entry, io) => {
            if (entry.isIntersecting && !played) {
                played = true;
                cb();
                io.disconnect?.();
            }
        };
    };
    const $ = (sel, root = document) => root.querySelector(sel);
    const $$ = (sel, root = document) => Array.from(root.querySelectorAll(sel));

    // Cache
    const top = $(".top__inner");

    if (window.gsap && top) {
        if (!top) return;

        // ===============================
        // 1) Title + Badge
        // ===============================
        const titleWrap = $(".top__title", top);
        const reveal = $(".reveal-target", top); // залишаємо, але не використовуємо на ≥1200
        const titleBadge = $(".top__title-badge", top);

        // брейкпоинт
        const m1200 = window.matchMedia('(min-width:1200px)');

        // === Инициализация состояний (оновлено для ≥1200) ===
        const setup1200 = () => {
            // нічого не маскуємо на десктопі
            if (reveal) gsap.set(reveal, { clearProps: "all" });

            // стартові стани: увесь блок заголовка «зліва й прозорий»,
            // бейдж прихований як і раніше
            if (titleWrap) gsap.set(titleWrap, { x: 48, autoAlpha: 0, willChange: "transform,opacity" });
            if (titleBadge) gsap.set(titleBadge, { y: 10, scale: 0.96, autoAlpha: 0, willChange: "transform,opacity" });
        };

        const setupBelow = () => {
            // старий підхід — як було
            if (titleBadge) gsap.set(titleBadge, { y: 10, scale: 0.96, autoAlpha: 0 });
        };

        // === Запуск анимации (оновлено для ≥1200) ===
        const run1200 = () => {
            const tl = gsap.timeline({ defaults: { ease: "power3.out" } });
            // 1) увесь заголовок виїжджає зліва та з’являється
            if (titleWrap) tl.to(titleWrap, { x: 0, autoAlpha: 1, duration: 0.6 });
            // 2) потім — бейдж із твоєю пружиною
            if (titleBadge) tl.to(titleBadge, { y: 0, scale: 1, autoAlpha: 1, duration: 0.6, ease: "elastic.out(1, 0.9)" }, "-=0.15");
        };

        const runBelow = () => {
            const tl = gsap.timeline({ defaults: { ease: "power2.out" } });
            if (titleBadge) {
                tl.to(titleBadge, { y: 0, scale: 1, autoAlpha: 1, duration: 0.6, ease: "elastic.out(1,0.9)" }, "-=0.25");
            }
        };

        // Подключаем IO (без змін)
        if (titleWrap) {
            if (m1200.matches) setup1200(); else setupBelow();

            const io = new IntersectionObserver(([entry]) => {
                if (!entry.isIntersecting) return;
                if (m1200.matches) run1200(); else runBelow();
                io.disconnect();
            }, IO_OPTIONS);

            io.observe(titleWrap);
        }

        // ===============================
        // 2) Buttons block(s)
        // ===============================

        const btnBlocks = $$(".top__btn-block", top);
        btnBlocks.forEach(block => {
            const btns = $$("a.button", block);
            if (btns.length) gsap.set(btns, { y: 16, autoAlpha: 0 });

            const ioBtns = new IntersectionObserver((entries, io) => {
                const e = entries[0];
                playOnce(() => {
                    // одночасно, без stagger
                    gsap.to(btns, {
                        y: 0,
                        autoAlpha: 1,
                        duration: 0.45,
                        ease: "power2.out"
                    });
                })(e, io);
            }, IO_OPTIONS);
            ioBtns.observe(block);
        });

        // ===============================
        // 3) Benefits list
        // ===============================
        const benefits = $$(".top__benefits-item", top);
        benefits.forEach(li => {
            const p = $("p", li);
            const path = $("svg path", li);

            if (p) gsap.set(p, { x: 10, autoAlpha: 0 });
            if (path) {
                const len = (typeof path.getTotalLength === "function") ? path.getTotalLength() : 284;
                path.style.fill = "none";
                path.style.stroke = "black";
                path.style.strokeWidth = 1;
                gsap.set(path, { strokeDasharray: len, strokeDashoffset: len });
            }

            const ioBen = new IntersectionObserver((entries, io) => {
                const e = entries[0];
                playOnce(() => {
                    const tl = gsap.timeline({ defaults: { ease: "power2.out" } });
                    if (p) tl.to(p, { x: 0, autoAlpha: 1, duration: 0.4 });
                    if (path) tl.to(path, { strokeDashoffset: 0, duration: 0.45 }, "-=0.22");
                })(e, io);
            }, IO_OPTIONS);

            ioBen.observe(li);
        });

        // ===============================
        // 4) Advantages list
        // ===============================
        const advantages = $$(".top__advantages-item", top);
        advantages.forEach((li, i) => {
            const imgWrap = $(".top__advantages-image", li);
            const img = $(".top__advantages-image img, .top__advantages-image picture, .top__advantages-image", li);
            const p = $("p", li);

            // PREP
            // картинка «поза» правим краєм і трохи повернута — для ефекту «викочування»
            if (img) gsap.set(img, { x: 60, rotate: 90, autoAlpha: 0, transformOrigin: "50% 50%" });
            if (p) gsap.set(p, { y: 10, autoAlpha: 0 });

            const ioAdv = new IntersectionObserver((entries, io) => {
                const e = entries[0];
                playOnce(() => {
                    const tl = gsap.timeline({ defaults: { ease: "power2.out" } });

                    // 1) «викочується» кругле зображення справа наліво з підкочуванням
                    if (img) {
                        tl.to(img, {
                            x: 0,
                            rotate: 0,
                            autoAlpha: 1,
                            duration: 0.75,
                            ease: "elastic.out(1, 0.9)"
                        });
                    }

                    // 2) Потім текст — як і було (не міняємо ефект)
                    if (p) {
                        tl.to(p, { y: 0, autoAlpha: 1, duration: 0.45 }, "-=0.25");
                    }
                })(e, io);
            }, IO_OPTIONS);

            // легке ритмічне зсування спрацювання (необов'язково)
            ioAdv.rootMargin = `${-i * 2}px 0px 0px 0px`;
            ioAdv.observe(li);
        });

    } // end GSAP animations



    const screenWidth = () => {
        let windowWidth;

        if (window.innerWidth) {
            windowWidth = window.innerWidth;
        } else if (
            document.documentElement &&
            document.documentElement.clientWidth
        ) {
            windowWidth = document.documentElement.clientWidth;
        } else if (document.body) {
            windowWidth = document.body.clientWidth;
        }
        return windowWidth;
    };


    // ========================= SWIPER INIT END============================

    // ========================= POP UP INIT START ============================
    //   const popup = document.getElementById("promoPopup");
    //   const closeBtn = document.getElementById("popupClose");

    //   let showCount = 2;

    //   function showPopup() {
    //     if (showCount >= 2) return;
    //     popup.classList.add("active");
    //     showCount++;
    //   }

    //   function hidePopup() {
    //     popup.classList.remove("active");
    //   }

    //   closeBtn.addEventListener("click", hidePopup);
    //   popup.querySelector(".promo-popup__overlay").addEventListener("click", hidePopup);

    //   // перший показ через 5 сек
    //   setTimeout(() => {
    //     showPopup();

    //     // другий показ через 10 сек після першого
    //     setTimeout(() => {
    //       showPopup();
    //     }, 10000);

    //   }, 50000);
    // ========================= POP UP INIT END ============================




    //  SWHITCH LOCALISATION  SWHITCH LOCALISATION  SWHITCH LOCALISATION

    var swhithLang = document.querySelectorAll(
        ".langCheck__item:not(.selected) input"
    );
    swhithLang.forEach(function (item) {
        item.addEventListener("change", function () {
            var val = item.name;
            location.reload();
            document.cookie = `content_lang=${val}; max-age=3600`;
        });
    });

    //  SWHITCH LOCALISATION  SWHITCH LOCALISATION  SWHITCH LOCALISATION

});
